<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Models\User;
use App\Services\{Administration as A,ProgrammeAccess};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,Mail};
use Illuminate\Support\Str;
use Illuminate\Validation\{Rule,ValidationException};
class PeopleController extends Controller {
 private function scope(Request $r,ProgrammeAccess $access):array {if(!$r->isMethod('GET'))abort_unless(\App\Services\Administration::freshVerification($r->user(),$r->session()),423,'Verify a fresh authenticator code before changing account access.');if(A::master($r->user()))return DB::table('programmes')->pluck('id')->all();$ids=$access->programmes($r->user(),'people.manage');abort_unless($ids,403);return $ids;}
 private function target(Request $r,User $user,array $ids):void {abort_unless($user->member_type==='staff'&&(A::master($r->user())||DB::table('programme_role_user')->where('user_id',$user->id)->whereIn('programme_id',$ids)->exists()),404);}
 public function index(Request $r,ProgrammeAccess $access){$ids=$this->scope($r,$access);$q=User::query()->where('member_type','staff');if(!A::master($r->user()))$q->whereIn('id',DB::table('programme_role_user')->whereIn('programme_id',$ids)->select('user_id'));return response()->json(['data'=>$q->orderBy('name')->get()->map(function($u)use($r,$ids){$p=A::person($u);if(!A::master($r->user())){$p['roles']=$p['roles']->whereIn('programme_id',$ids)->values();$p['overrides']=[];}return $p;}),'roles'=>DB::table('roles')->get(['id','name']),'permissions'=>DB::table('permissions')->pluck('name'),'programmes'=>DB::table('programmes')->whereIn('id',$ids)->get(['id','name'])]);}
 public function store(Request $r,ProgrammeAccess $access){$ids=$this->scope($r,$access);$r->merge(['email'=>strtolower(trim((string)$r->input('email')))]);$d=$r->validate(['name'=>'required|string|max:150','email'=>'required|email|max:254|unique:users,email','type'=>['required',Rule::in(['staff'])],'programme_id'=>['required','integer',Rule::in($ids)],'role_ids'=>'required|array|min:1','role_ids.*'=>'required|integer|distinct|exists:roles,id','expires_at'=>'nullable|date|after:now','mode'=>['required',Rule::in(['create','invite'])]]);if($d['type']==='external')abort_if(DB::table('roles')->whereIn('id',$d['role_ids'])->where('name','Programme Administrator')->exists(),422,'External accounts cannot hold staff administration roles.');if($d['mode']==='create')abort_unless(A::master($r->user()),403);if(!A::master($r->user())){ $allowed=DB::table('roles')->whereIn('name',['Evaluator','Adjudicator','Viewer'])->pluck('id')->all();abort_unless(!array_diff($d['role_ids'],$allowed),403);}
  $result=DB::transaction(function()use($r,$d){$u=new User(['name'=>$d['name'],'email'=>strtolower($d['email']),'password'=>Str::random(60)]);$u->account_status='invited';$u->member_type=$d['type'];$u->access_expires_at=$d['expires_at']??null;$u->save();foreach($d['role_ids'] as $role)DB::table('programme_role_user')->insert(['user_id'=>$u->id,'role_id'=>$role,'programme_id'=>$d['programme_id']]);A::audit($r->user(),'account.'.$d['mode'],'user',$u->id,['roles'=>$d['role_ids']],$d['programme_id']);return [$u,$this->issue($u)];});
  [$u,$token]=$result;$url=url('/activate?token='.$token);$delivery='manual';if(!in_array(config('mail.default'),['log','array'])){\App\Jobs\DeliverInvitation::dispatch($u->id,$token)->afterCommit();$delivery='queued';}DB::table('staff_invitations')->where('token_hash',hash('sha256',$token))->update(['delivery_status'=>$delivery]);A::audit($r->user(),'invitation.delivery','user',$u->id,['delivery'=>$delivery]);return response()->json(['data'=>A::person($u),'activation_url'=>$delivery==='queued'?null:$url,'delivery'=>$delivery],201)->header('Cache-Control','no-store');
 }
 public function bulk(Request $r,ProgrammeAccess $access){$this->scope($r,$access);$d=$r->validate(['emails'=>'required|array|min:1|max:200','emails.*'=>'required|string|max:254','programme_id'=>'required|integer','role_ids'=>'required|array|min:1','role_ids.*'=>'integer','type'=>'required|in:staff']);$results=[];foreach(array_unique(array_map(fn($v)=>strtolower(trim($v)),$d['emails'])) as $email){if(!filter_var($email,FILTER_VALIDATE_EMAIL)){$results[]=['email'=>$email,'status'=>'invalid'];continue;}if(User::where('email',$email)->exists()){$results[]=['email'=>$email,'status'=>'already_exists'];continue;}$item=$r->duplicate();$item->replace(['name'=>explode('@',$email)[0],'email'=>$email,'type'=>$d['type'],'programme_id'=>$d['programme_id'],'role_ids'=>$d['role_ids'],'mode'=>'invite']);try{$response=$this->store($item,$access);$body=$response->getData(true);$results[]=['email'=>$email,'status'=>$body['delivery'],'activation_url'=>$body['activation_url']??null];}catch(\Illuminate\Validation\ValidationException $e){$results[]=['email'=>$email,'status'=>'invalid','errors'=>$e->errors()];}}return ['data'=>$results];}
 private function issue(User $u):string {$token=Str::random(64);DB::table('staff_invitations')->where('user_id',$u->id)->whereNull('accepted_at')->update(['revoked_at'=>now()]);DB::table('staff_invitations')->insert(['user_id'=>$u->id,'token_hash'=>hash('sha256',$token),'expires_at'=>now()->addDays(7),'created_at'=>now(),'updated_at'=>now()]);return $token;}
 public function update(Request $r,User $user,ProgrammeAccess $access){$ids=$this->scope($r,$access);$this->target($r,$user,$ids);$d=$r->validate(['action'=>['required',Rule::in(['suspend','reactivate','revoke','access','profile','reinvite','reset_password'])],'programme_id'=>['nullable','integer',Rule::in($ids)],'role_ids'=>'sometimes|array','role_ids.*'=>'integer|distinct|exists:roles,id','overrides'=>'sometimes|array','overrides.*.permission'=>['required','distinct',Rule::in(DB::table('permissions')->pluck('name')->all())],'overrides.*.allowed'=>'required|boolean','expertise'=>'nullable|string|max:200','expires_at'=>'nullable|date|after:now']);
  if($d['action']==='reset_password')abort_unless((!\App\Services\Administration::requiresMfa($r->user())||$r->session()->pull('password_reset_confirmed_at',0)>time()-60),423,'Confirm a fresh authenticator code for this password reset.');
  return DB::transaction(function()use($r,$user,$d,$ids){$u=User::lockForUpdate()->findOrFail($user->id);abort_unless($u->member_type==='staff',404);abort_if($u->is_master||$u->id===$r->user()->id,403,'This account is protected.');$action=$d['action'];$pid=$d['programme_id']??null;
   if($action==='access'){abort_unless($pid,403);if(!A::master($r->user())){$safe=DB::table('roles')->whereIn('name',['Evaluator','Adjudicator','Viewer'])->pluck('id')->all();abort_if(array_diff($d['role_ids']??[],$safe)||!empty($d['overrides']),403,'Administrators can assign reviewer and viewer roles only.');abort_if(DB::table('programme_role_user')->where('user_id',$u->id)->whereNotIn('role_id',$safe)->exists(),403,'This account requires Master Administrator access.');}if($u->member_type==='external'){abort_if(DB::table('roles')->whereIn('id',$d['role_ids']??[])->where('name','Programme Administrator')->exists(),422,'External accounts cannot hold staff administration roles.');abort_if(collect($d['overrides']??[])->contains(fn($o)=>$o['allowed']&&in_array($o['permission'],['people.manage','templates.manage','reviews.manage'],true)),422,'External accounts cannot receive staff administration permissions.');}DB::table('programme_role_user')->where('user_id',$u->id)->where('programme_id',$pid)->delete();foreach($d['role_ids']??[] as $role)DB::table('programme_role_user')->insert(['user_id'=>$u->id,'programme_id'=>$pid,'role_id'=>$role]);if(A::master($r->user())){DB::table('access_overrides')->where('user_id',$u->id)->where('programme_id',$pid)->delete();foreach($d['overrides']??[] as $override)DB::table('access_overrides')->insert(['user_id'=>$u->id,'programme_id'=>$pid,...$override]);}}
   elseif($action==='profile'){abort_unless(A::master($r->user()),403);$u->expertise=$d['expertise']??null;$u->access_expires_at=$d['expires_at']??null;}
   else {if(!A::master($r->user())){$roles=DB::table('programme_role_user as p')->join('roles','roles.id','=','p.role_id')->where('user_id',$u->id)->get(['p.programme_id','roles.name']);abort_if($roles->contains(fn($x)=>!in_array($x->programme_id,$ids)||!in_array($x->name,['Evaluator','Adjudicator','Viewer'])),403);}
    if($action==='suspend'){abort_unless($u->account_status==='active',422);$u->account_status='suspended';}
    if($action==='reactivate'){abort_unless($u->account_status==='suspended',422);$u->account_status='active';}
    if($action==='revoke'){abort_unless($u->account_status==='invited',422);$u->account_status='revoked';DB::table('staff_invitations')->where('user_id',$u->id)->update(['revoked_at'=>now()]);}
    if($action==='reset_password'){(new \App\Services\AccountChallenges)->issue($u,'reset','email');}if($action==='reinvite'){abort_unless(in_array($u->account_status,['invited','revoked']),422);$u->account_status='invited';$token=$this->issue($u);if(!in_array(config('mail.default'),['log','array']))\App\Jobs\DeliverInvitation::dispatch($u->id,$token)->afterCommit();}
   }
   $u->save();if(in_array($action,['suspend','revoke','access']))DB::table('sessions')->where('user_id',$u->id)->delete();A::audit($r->user(),'account.'.$action,'user',$u->id,$d,$pid);return response()->json(['data'=>A::person($u),'activation_url'=>isset($token)?url('/activate?token='.$token):null])->header('Cache-Control','no-store');
  });
 }
 public function history(Request $r,User $user,ProgrammeAccess $access){$ids=$this->scope($r,$access);$this->target($r,$user,$ids);$q=DB::table('audit_events')->where('subject_type','user')->where('subject_id',$user->id);if(!A::master($r->user()))$q->whereIn('programme_id',$ids);return ['data'=>$q->orderByDesc('id')->limit(100)->get()];}
 public function activate(Request $r){$d=$r->validate(['token'=>'required|string|size:64','password'=>'required|string|min:8|max:12|confirmed','confidentiality'=>'accepted','name'=>'nullable|string|max:150']);DB::transaction(function()use($d){$invite=DB::table('staff_invitations')->where('token_hash',hash('sha256',$d['token']))->lockForUpdate()->first();if(!$invite||$invite->revoked_at||$invite->accepted_at||now()->gte($invite->expires_at))throw ValidationException::withMessages(['token'=>'This invitation is expired, revoked or already used.']);$u=User::lockForUpdate()->findOrFail($invite->user_id);abort_unless($u->account_status==='invited',422);$u->password=$d['password'];if(!empty($d['name']))$u->name=$d['name'];$u->account_status='active';$u->email_verified_at=now();$u->save();DB::table('staff_invitations')->where('id',$invite->id)->update(['accepted_at'=>now(),'confidentiality_accepted_at'=>now()]);A::audit($u,'invitation.accepted','user',$u->id);});return ['message'=>'Account activated. You can sign in.'];}
}
